// Copies the app's own captures and font files into this project.
//
// The composition renders the real Ledgerly screenshots, so this keeps a single
// source of truth: the images come from docs/screenshots/ (regenerated by
// `npm run screenshots`) and the fonts from static/fonts/. HyperFrames cannot
// load assets from above the project root, so they have to be copied in.
//
//   node tools/preview/scripts/sync-assets.mjs
//
// Development tooling only: the copies are gitignored and ship with nothing.

import { copyFileSync, mkdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const project = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const repo = resolve(project, "..", "..");

const files = [
  ["docs/screenshots/desktop/01-dashboard.png", "assets/01-dashboard.png"],
  ["docs/screenshots/desktop/02-invoices.png", "assets/02-invoices.png"],
  ["docs/screenshots/desktop/04-invoice-editor.png", "assets/04-invoice-editor.png"],
  ["docs/screenshots/desktop/08-estimates.png", "assets/08-estimates.png"],
  ["docs/screenshots/desktop/09-estimate-detail.png", "assets/09-estimate-detail.png"],
  ["docs/screenshots/desktop/10-reports.png", "assets/10-reports.png"],
  ["static/fonts/Inter-Regular.ttf", "assets/fonts/Inter-Regular.ttf"],
  ["static/fonts/Inter-Bold.ttf", "assets/fonts/Inter-Bold.ttf"],
];

for (const [from, to] of files) {
  const target = join(project, to);
  mkdirSync(dirname(target), { recursive: true });
  copyFileSync(join(repo, from), target);
}

console.log(`Synced ${files.length} assets from the app into ${join(project, "assets")}`);
